<?php require_once __DIR__.'/../includes/bootstrap.php';require_customer();$c=customer_row();$title='Change Password';$errors=[];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');if(!password_verify($old,$c['password_hash']))$errors[]='Old password is incorrect.';elseif(strlen($new)<8)$errors[]='New password must be at least 8 characters.';elseif($new!==$confirm)$errors[]='New password and confirmation do not match.';else{$pdo->prepare('UPDATE customers SET password_hash=?,updated_at=NOW() WHERE customer_id=?')->execute([password_hash($new,PASSWORD_DEFAULT),(int)$c['customer_id']]);$msg='Password changed successfully.';}}require __DIR__.'/../includes/header.php';?><div class="section-head"><div><span class="eyebrow">ACCOUNT SECURITY</span><h1>Change password</h1></div></div><?php if($msg):?><div class="flash success"><?=e($msg)?></div><?php endif;?><?php if($errors):?><div class="errors"><?=e($errors[0])?></div><?php endif;?><section class="panel narrow"><form method="post" class="form"><?=csrf_field()?><label>Old password<input type="password" name="old_password" required autocomplete="current-password"></label><label>New password<input type="password" name="new_password" minlength="8" required autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm_password" minlength="8" required autocomplete="new-password"></label><button class="btn primary">Change password</button></form></section><?php require __DIR__.'/../includes/footer.php';?>